-- Platform Updates archive and implementation checklist.
create table if not exists public.platform_updates (
  pr_number integer primary key,
  title text not null,
  summary text not null,
  merged_at timestamptz not null,
  url text not null,
  created_at timestamptz not null default now()
);
create index if not exists platform_updates_merged_at_idx on public.platform_updates (merged_at desc);
create index if not exists platform_updates_title_search_idx on public.platform_updates using gin (to_tsvector('english', title || ' ' || summary));

create table if not exists public.platform_implementation_tasks (
  id uuid primary key default gen_random_uuid(),
  title text not null check (length(trim(title)) between 3 and 180),
  description text not null default '' check (length(description) <= 5000),
  category text not null default 'Platform' check (length(category) <= 80),
  status text not null default 'planned' check (status in ('planned','in_progress','blocked','completed','cancelled')),
  priority text not null default 'medium' check (priority in ('low','medium','high','critical')),
  progress integer not null default 0 check (progress between 0 and 100),
  due_date date,
  sort_order integer not null default 0,
  created_by uuid,
  updated_by uuid,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  completed_at timestamptz
);
create index if not exists platform_tasks_status_idx on public.platform_implementation_tasks(status, priority, due_date);
create index if not exists platform_tasks_updated_idx on public.platform_implementation_tasks(updated_at desc);

create table if not exists public.platform_implementation_task_events (
  id bigint generated always as identity primary key,
  task_id uuid not null references public.platform_implementation_tasks(id) on delete cascade,
  actor_id uuid,
  event_type text not null,
  detail jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now()
);
create index if not exists platform_task_events_task_idx on public.platform_implementation_task_events(task_id, created_at desc);

create or replace function public.platform_tasks_touch_updated_at()
returns trigger language plpgsql as $$
begin
  new.updated_at := now();
  if new.status = 'completed' and old.status is distinct from 'completed' then
    new.completed_at := now();
    new.progress := 100;
  elsif new.status <> 'completed' then
    new.completed_at := null;
  end if;
  return new;
end;
$$;
drop trigger if exists platform_tasks_touch_updated_at on public.platform_implementation_tasks;
create trigger platform_tasks_touch_updated_at before update on public.platform_implementation_tasks
for each row execute function public.platform_tasks_touch_updated_at();

alter table public.platform_updates enable row level security;
alter table public.platform_implementation_tasks enable row level security;
alter table public.platform_implementation_task_events enable row level security;
revoke all on public.platform_updates from anon, authenticated;
revoke all on public.platform_implementation_tasks from anon, authenticated;
revoke all on public.platform_implementation_task_events from anon, authenticated;
grant select, insert, update, delete on public.platform_updates to service_role;
grant select, insert, update, delete on public.platform_implementation_tasks to service_role;
grant select, insert, update, delete on public.platform_implementation_task_events to service_role;
grant usage, select on sequence public.platform_implementation_task_events_id_seq to service_role;

on conflict (pr_number) do update set title=excluded.title, summary=excluded.summary, merged_at=excluded.merged_at, url=excluded.url;

values ('Launch Fantasy Arena 3.0','Release Fantasy Arena as a core fantasy sports competition with H2H Duels and the existing Practice Mode capabilities, following the approved Week 2–3 post-launch roadmap window.','Product roadmap','planned','high',0,'2026-12-15',10)
on conflict do nothing;
